head.script:


            scwin.getType = function ( info ) {

                var rowIndex = info.rowIndex;
                var colIndex = info.colIndex;
                var returnInfo;


                if(dataList1.getCellData(rowIndex, "col2") == 1){
                	returnInfo = {
		                id : "dynamic_text_" + rowIndex + "_" + colIndex,
						inputType : "text"
					};
                }else if(dataList1.getCellData(rowIndex, "col2") == 2){
                	returnInfo = {
		                id : "dynamic_text_" + rowIndex + "_" + colIndex,
						inputType : "text"
					};                
                }else if(dataList1.getCellData(rowIndex, "col2") == 3 || dataList1.getCellData(rowIndex, "col2") == 4){
                	returnInfo = {
		                id : "dynamic_select_" + rowIndex + "_" + colIndex,
						inputType : "select",
						options : {
							viewType: "icon"
						},
						itemSet : {
							nodeset : "data:dataList3",
							label : "col1",
							value : "col2"
						}
					};
                } else {
					returnInfo = {
		                id : "dynamic_text_" + rowIndex + "_" + colIndex,
						inputType : "text",
						options : {
						}
					};


                }


                return returnInfo;

			};

	scwin.onpageload = function() {

		var jsonData = [{"col2":"1"},{"col2":"2"},{"col2":"3"},{"col2":"4"}];
	    dataList1.setJSON( jsonData );

		var jsonData2 = [{"col1":"a1","col2":"a1"},{"col1":"a2","col2":"a2"},{"col1":"a3","col2":"a3"}];
	    dataList2.setJSON( jsonData2 );

	    var jsonData3 = [{"col1":"b1","col2":"b1"},{"col1":"b2","col2":"b2"},{"col1":"b3","col2":"b3"}];
	    dataList3.setJSON( jsonData3 );

	};

	scwin.onpageunload = function() {

	};


	scwin.Dbclick = function(id) {
		var el = WebSquare.wUnit.getDomById(id);
		scwin.fireDbClick(el);
	}
	scwin.fireDbClick = function(node) {
		if (document.createEventObject) {
			node.fireEvent('ondblclick');
		} else if (document.createEvent) {
			var evt = document.createEvent('MouseEvents');
			evt.initEvent('dblclick', true, false);
			node.dispatchEvent(evt);
		} else if (typeof node.ondblclick == 'function') {
			node.ondblclick();
		}
	}	

	scwin.simulateWrapper = function(target, type, options) {
		WebSquare.wUnit.getJq(target).simulate(type, options);
	}
	scwin.setSimulate1 = function() {
		scwin.simulateWrapper('#grd_cell_0_0', 'key-combo', {
			combo: 'TAB'
		});
	}
	scwin.checkVal = function() {
		return WebSquare.wUnit.getJq("#wq_uuid_4_cell_0_2").hasClass('focusedTd');
	}	
	scwin.checkVal = function() {
		return WebSquare.wUnit.getJq('#grd_dynamic_text_1_0').hasClass('w2input_focus');
	}
	scwin.unitTest = function() {
		//Unit
		WebSquare.wUnit.start();
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('grd_cell_0_0').click()");
		WebSquare.wUnit.addCommand("pause", "400");			

		WebSquare.wUnit.addCommand("set", "scwin.setSimulate1()");
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("set", "scwin.setSimulate1()");
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("set", "scwin.setSimulate1()");
		WebSquare.wUnit.addCommand("pause", "500");

		WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
		WebSquare.wUnit.addCommand("pause", "500");
		//Run test and stop
		WebSquare.wUnit.run();
		WebSquare.wUnit.stop();
	}	
	scwin.unitTest()
